/* global Office, Excel, console */

Office.onReady((info) => {
    if (info.host === Office.HostType.Excel) {
        console.log("EXAI Pro sẵn sàng.");
        document.getElementById("run_button").onclick = executeCommand;
        document.getElementById("clear_button").onclick = clearAll;

        const savedKey = localStorage.getItem("gemini_api_key");
        if (savedKey) document.getElementById("api_key_input").value = savedKey;
        const savedModel = localStorage.getItem("gemini_model");
        if (savedModel) document.getElementById("model_select").value = savedModel;
    }
});

function setStatus(message, type) {
    const el = document.getElementById("status_area");
    el.className = "status " + type;
    el.innerText = message;
}

// Lấy bối cảnh sheet
async function getSheetContext() {
    let info = "";
    await Excel.run(async (context) => {
        const selected = context.workbook.getSelectedRange();
        selected.load("address, rowCount, columnCount, values");
        const used = context.workbook.worksheets.getActiveWorksheet().getUsedRangeOrNullObject();
        used.load("address, text");
        const sheetObj = context.workbook.worksheets.getActiveWorksheet();
        sheetObj.load("name");
        await context.sync();

        info += `Tên sheet: ${sheetObj.name}\n`;
        info += `Vùng ĐANG CHỌN: ${selected.address} (${selected.rowCount} dòng x ${selected.columnCount} cột)\n`;
        info += `Dữ liệu vùng đang chọn: ${JSON.stringify(selected.values)}\n`;
        if (!used.isNullObject) {
            info += `Toàn bộ vùng có dữ liệu: ${used.address}\n`;
            let preview = used.text.slice(0, 30).map(r => r.join(" | ")).join("\n");
            info += `Xem trước dữ liệu:\n${preview}\n`;
        }
    });
    return info;
}

// Gọi Gemini
async function callGemini(apiKey, model, prompt) {
    const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                contents: [{ parts: [{ text: prompt }] }],
                generationConfig: { temperature: 0.1, maxOutputTokens: 4096 }
            })
        }
    );
    const data = await response.json();
    if (!response.ok) throw new Error(data.error?.message || "Lỗi API");
    if (!data.candidates || data.candidates.length === 0) throw new Error("Không nhận được phản hồi.");
    let text = data.candidates[0].content.parts.map(p => p.text).join(" ").trim();
    return text;
}

// Làm sạch code
function cleanCode(code) {
    code = code.replace(/```javascript/gi, "").replace(/```js/gi, "").replace(/```/g, "").trim();
    // Bỏ wrapper Excel.run nếu AI lỡ viết
    code = code.replace(/^[\s\S]*?await\s+Excel\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i, "");
    code = code.replace(/await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i, "");
    code = code.trim();
    return code;
}

// Chạy code do AI tạo
async function runGeneratedCode(code) {
    await Excel.run(async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const workbook = context.workbook;
        const runner = new Function("context", "sheet", "workbook", "Excel",
            `return (async () => { ${code} \n await context.sync(); })();`);
        await runner(context, sheet, workbook, Excel);
        await context.sync();
    });
}

const SYSTEM_RULES = `Bạn là chuyên gia lập trình Office.js điều khiển Microsoft Excel.
Người dùng ra lệnh bằng tiếng Việt. Nhiệm vụ: viết code JavaScript Office.js thực hiện CHÍNH XÁC yêu cầu.

QUY TẮC TRẢ VỀ:
- CHỈ trả về code JavaScript thuần. TUYỆT ĐỐI KHÔNG giải thích, KHÔNG markdown, KHÔNG backtick.
- Code được chạy BÊN TRONG: await Excel.run(async (context) => { [CODE BẠN VIẾT] await context.sync(); });
- KHÔNG tự viết "await Excel.run(...)" và "await context.sync()" ở cuối - đã có sẵn.
- Có sẵn các biến: context, sheet (worksheet active), workbook, Excel.

CÁCH DÙNG API:
- Vùng đang chọn: const sel = workbook.getSelectedRange();
- Ô/vùng cụ thể: sheet.getRange("D3") hoặc sheet.getRange("A1:A10")
- ĐỌC dữ liệu: range.load("values, rowCount, columnCount, address"); await context.sync(); rồi dùng range.values
- Ghi giá trị: range.values = [[1],[2]]; (mảng 2 chiều)
- Ghi công thức: range.formulas = [["=SUM(A1:A10)"]];
- Font: range.format.font.name = "Times New Roman"; range.format.font.size = 13; range.format.font.bold = true; range.format.font.color = "#FF0000";
- Nền: range.format.fill.color = "#FFFF00";
- Căn: range.format.horizontalAlignment = "Center"; verticalAlignment = "Center";
- Viền: range.format.borders.getItem("EdgeBottom").style = "Continuous";
- Sắp xếp: range.sort.apply([{key: 0, ascending: true}]);
- Định dạng số: range.numberFormat = [["#,##0"]];
- Xóa nội dung: range.clear();
- Auto-fit cột: range.format.autofitColumns();
- Gộp ô: range.merge();

XỬ LÝ LOGIC PHỨC TẠP (lọc trùng, tính toán tùy chỉnh...):
- ĐỌC dữ liệu vào biến JS, xử lý bằng JS thuần, rồi GHI kết quả ra range.
- Ví dụ lọc giá trị không trùng:
  const src = workbook.getSelectedRange();
  src.load("values");
  await context.sync();
  const flat = src.values.flat().filter(v => v !== "" && v !== null);
  const unique = [...new Set(flat)];
  const out = unique.map(v => [v]);
  sheet.getRange("F1").getResizedRange(unique.length - 1, 0).values = out;

QUAN TRỌNG:
- Luôn thêm await context.sync(); sau khi load() để đọc được dữ liệu trước khi xử lý.
- Nếu cần ghi mảng động, dùng getResizedRange(soDong-1, soCot-1).
- Suy luận thông minh ô đích nếu người dùng không nói rõ.`;

async function executeCommand() {
    const apiKey = document.getElementById("api_key_input").value.trim();
    const model = document.getElementById("model_select").value;
    const userPrompt = document.getElementById("prompt_input").value.trim();
    const btn = document.getElementById("run_button");

    if (!apiKey) { setStatus("⚠️ Vui lòng nhập API key.", "error"); return; }
    if (!userPrompt) { setStatus("⚠️ Vui lòng nhập yêu cầu.", "error"); return; }

    localStorage.setItem("gemini_api_key", apiKey);
    localStorage.setItem("gemini_model", model);
    btn.disabled = true;
    setStatus("⏳ Đang phân tích yêu cầu...", "loading");

    try {
        const contextInfo = await getSheetContext();
        const fullPrompt = `${SYSTEM_RULES}\n\nBỐI CẢNH EXCEL HIỆN TẠI:\n${contextInfo}\n\nYÊU CẦU NGƯỜI DÙNG: ${userPrompt}`;

        let code = await callGemini(apiKey, model, fullPrompt);
        code = cleanCode(code);
        console.log("=== Code AI tạo ===\n", code);

        try {
            setStatus("⚙️ Đang thực thi...", "loading");
            await runGeneratedCode(code);
            setStatus("✅ Đã thực thi thành công!", "success");
        } catch (execError) {
            // Tự động sửa lỗi: gửi lại code + lỗi cho AI
            console.warn("Lỗi lần 1, đang thử sửa:", execError.message);
            setStatus("🔄 Gặp lỗi, đang tự sửa...", "loading");

            const fixPrompt = `${SYSTEM_RULES}\n\nBỐI CẢNH:\n${contextInfo}\n\nYÊU CẦU: ${userPrompt}\n\nCode trước đó bị lỗi:\n${code}\n\nLỖI: ${execError.message}\n\nHãy viết lại code ĐÚNG. Chỉ trả về code.`;
            let fixedCode = await callGemini(apiKey, model, fixPrompt);
            fixedCode = cleanCode(fixedCode);
            console.log("=== Code sửa lại ===\n", fixedCode);

            await runGeneratedCode(fixedCode);
            setStatus("✅ Đã thực thi thành công (sau khi tự sửa)!", "success");
        }

    } catch (error) {
        console.error(error);
        setStatus("❌ Lỗi: " + error.message, "error");
    } finally {
        btn.disabled = false;
    }
}

function clearAll() {
    document.getElementById("prompt_input").value = "";
    document.getElementById("status_area").className = "status";
    document.getElementById("status_area").innerText = "";
}